import csv, collections
cp='inputs/JD_AgeRelated_CpG_noMT_Final.csv'; lenp='inputs/JD_Chromosome_Length.csv'
lengths={}
with open(lenp,newline='',encoding='utf-8-sig') as f:
    for r in csv.DictReader(f): lengths[r['Chromosome']]=int(r['Length'])
unique={}
with open(cp,newline='') as f:
    for r in csv.DictReader(f):
        m=float(r['MethylationPercentage'])
        if m>90 or m<10: unique[r['Pos']]=r['Chromosome']
counts=collections.Counter(unique.values())
included={c:lengths[c] for c in counts if c in lengths}
print(sum(included.values()), sum(counts[c] for c in included), sum(counts[c] for c in included)/sum(included.values()))
PY"
